// Turns all page findings into one prioritized backlog
const pages = $input.all().map(item => item.json);

// How important each page type is (1 to 3)
const PAGE_WEIGHT = { page: 3, guides: 2, 'success-stories': 2, blog: 1 };

// For each finding type: how bad it is (1 to 3), how hard to fix (1 to 3), who fixes it
const RULES = {
  title_missing:      { weight: 3, effort: 1, owner: 'content' },
  title_too_long:     { weight: 2, effort: 1, owner: 'content' },
  title_too_short:    { weight: 1, effort: 1, owner: 'content' },
  meta_missing:       { weight: 3, effort: 1, owner: 'content' },
  meta_too_long:      { weight: 2, effort: 1, owner: 'content' },
  meta_too_short:     { weight: 1, effort: 1, owner: 'content' },
  h1_missing:         { weight: 3, effort: 1, owner: 'content' },
  h1_multiple:        { weight: 2, effort: 1, owner: 'content' },
  canonical_missing:  { weight: 2, effort: 1, owner: 'developer' },
  canonical_other:    { weight: 1, effort: 1, owner: 'developer' },
  no_structured_data: { weight: 2, effort: 2, owner: 'developer' },
  img_missing_alt:    { weight: 1, effort: 1, owner: 'content' },
  answer_first:       { weight: 2, effort: 1, owner: 'content' },
  clear_audience:     { weight: 2, effort: 1, owner: 'content' },
  specific_facts:     { weight: 2, effort: 2, owner: 'content' },
  answers_questions:  { weight: 3, effort: 2, owner: 'content' },
  fits_purpose:       { weight: 2, effort: 3, owner: 'content' }
};
const DEFAULT_RULE = { weight: 1, effort: 2, owner: 'content' };

// Plain summary text for a Claude finding that shows up on many pages
const PATTERN_TEXT = {
  answer_first:      "don't open with a direct answer to what the page is about",
  specific_facts:    'lack concrete, quotable facts (numbers, prices, timelines)',
  clear_audience:    "don't clearly say who they are for",
  answers_questions: "don't answer the questions a buyer would ask an AI",
  fits_purpose:      "don't fully match the page's purpose"
};

// 1. One row per finding, from both the rules and Claude
const rows = [];
for (const page of pages) {
  const pageWeight = PAGE_WEIGHT[page.page_type] || 1;
  for (const f of page.rule_findings || []) {
    rows.push({ type: f.rule, source: 'rules', label: f.label, url: page.url, page_type: page.page_type,
      pageWeight, detail: f.message, evidence: String(f.value), needs_review: false });
  }
  for (const g of page.geo_issues || []) {
    rows.push({ type: g.criterion, source: 'claude', label: 'issue', url: page.url, page_type: page.page_type,
      pageWeight, detail: g.suggestion, evidence: g.evidence, needs_review: !g.evidence_found });
  }
}

// 2. Group: a finding on 3+ pages AND at least half of all pages is site-wide
//    Rules  -> one "template" row (one fix in the site template)
//    Claude -> one "pattern" summary row PLUS one row per page (each page needs its own text fix)
const totalPages = pages.length;
const byType = {};
for (const row of rows) (byType[row.type] = byType[row.type] || []).push(row);

const makeRow = (type, set, scope, detail, evidence) => {
  const rule = RULES[type] || DEFAULT_RULE;
  const first = set[0];
  const impact = rule.weight * Math.max(...set.map(r => r.pageWeight));
  const effort = rule.effort;
  return {
    finding: type,
    source: first.source,
    scope,
    pages_affected: set.length,
    example_url: first.url,
    page_type: set.length > 1 ? 'several' : first.page_type,
    label: first.label,
    owner: rule.owner,
    impact,
    effort,
    priority: Math.round(impact / effort * 10) / 10,
    quadrant: impact >= 4 ? (effort <= 1 ? 'Quick Win' : 'Big Bet') : (effort <= 1 ? 'Fill-in' : 'Deprioritize'),
    detail,
    evidence,
    needs_review: set.some(r => r.needs_review)
  };
};

const backlog = [];
for (const [type, group] of Object.entries(byType)) {
  const siteWide = group.length >= 3 && group.length >= totalPages / 2;
  const isClaude = group[0].source === 'claude';
  const countText = `${group.length} of ${totalPages} pages`;

  if (siteWide && !isClaude) {
    backlog.push(makeRow(type, group, 'template', group[0].detail, countText));
    continue;
  }
  if (siteWide && isClaude) {
    const summary = `${countText} ${PATTERN_TEXT[type] || 'share this issue'}. Treat as a content guideline; see the page rows for each page's own fix.`;
    backlog.push(makeRow(type, group, 'pattern', summary, countText));
  }
  for (const row of group) {
    backlog.push(makeRow(type, [row], 'page', row.detail, row.evidence));
  }
}

// 3. Highest priority first (a pattern row comes before its page rows)
const scopeOrder = { template: 0, pattern: 0, page: 1 };
backlog.sort((a, b) => b.priority - a.priority || scopeOrder[a.scope] - scopeOrder[b.scope] || b.pages_affected - a.pages_affected);
return backlog.map((row, i) => ({ json: { rank: i + 1, ...row } }));
